create or replace function public.set_role_fee_policy(p_role_code text,p_enabled boolean,p_amount numeric,p_currency text default 'NGN',p_review_hours integer default 24) returns public.role_fee_policies language plpgsql security definer set search_path=public as $$ declare v public.role_fee_policies; begin if not public.is_super_admin() then raise exception 'Super Admin access required'; end if; if p_role_code not in ('ARTIST','ORGANIZER','VENUE_MANAGER') then raise exception 'Invalid role code'; end if; if p_amount < 0 then raise exception 'Fee cannot be negative'; end if; update public.role_fee_policies set enabled=coalesce(p_enabled,true),amount=p_amount,currency=coalesce(nullif(trim(p_currency),''),'NGN'),organizer_review_hours=greatest(1,least(coalesce(p_review_hours,24),720)),updated_by=auth.uid(),updated_at=now() where role_code=p_role_code returning * into v; if v.role_code is null then raise exception 'Fee policy not found'; end if; return v; end; $$; revoke all on function public.set_role_fee_policy(text,boolean,numeric,text,integer) from public; grant execute on function public.set_role_fee_policy(text,boolean,numeric,text,integer) to authenticated;
